export async function createActivityDefinition(
  page: Page,
  facilityId: string,
  allFields: boolean = false,
  overrides: Partial<
    Pick<ActivityDefinitionData, "status" | "classification">
  > = {},
): Promise<ActivityDefinitionData> {
